#include <iostream>

// Recursive GCD with call depth visualization
int gcdTrace(int a, int b, int depth = 0) {
    for (int i = 0; i < depth; ++i) {
        std::cout << "  ";
    }
    std::cout << "gcd(" << a << ", " << b << ")\n";
    if (b == 0) {
        return a;
    }
    return gcdTrace(b, a % b, depth + 1);
}

int main() {
    int x = 48;
    int y = 18;
    std::cout << "Tracing Euclidean GCD for " << x << " and " << y << ":\n";
    int result = gcdTrace(x, y);
    std::cout << "Final GCD: " << result << "\n";
    return 0;
}

#include <iostream>

// Global variable to demonstrate unary scope resolution
int value = 100;

// Function template minimum
template <typename T>
T minimum(T a, T b) {
    return (a < b) ? a : b;
}

// C++11 Scoped enum
enum class AccountType {
    SAVINGS,
    CHECKING,
    INVESTMENT
};

void printAccountInfo(AccountType type) {
    std::cout << "Account category: ";
    switch (type) {
        case AccountType::SAVINGS:
            std::cout << "Savings Account\n";
            break;
        case AccountType::CHECKING:
            std::cout << "Checking Account\n";
            break;
        case AccountType::INVESTMENT:
            std::cout << "Investment Account\n";
            break;
    }
}

int main() {
    int value = 42; // Local variable shadowing global value
    std::cout << "Local value: " << value << ", Global value: " << ::value << "\n";

    std::cout << "Minimum int: " << minimum(15, 28) << "\n";
    std::cout << "Minimum char: " << minimum('z', 'b') << "\n";
    std::cout << "Minimum double: " << minimum(3.14, 2.71) << "\n";

    printAccountInfo(AccountType::SAVINGS);
    return 0;
}
